import { beforeEach, expect, it, vi } from 'vitest'
import backendJson from '@/components/catalog/fixtures/catalogIdentity.backend.json'
import type { CatalogIdentityPreviewInput, CatalogIdentityRequestView, CatalogIdentityReceipt, CatalogIdentityRef } from '@/api/catalogIdentity'
const api = vi.hoisted(() => ({ preview: vi.fn(), confirm: vi.fn(), lookup: vi.fn() }))
vi.mock('@/api/catalogIdentity', async original => ({ ...await original<object>(), previewCatalogIdentity: api.preview, confirmCatalogIdentity: api.confirm, getCatalogIdentityRequestByKey: api.lookup }))
import { useCatalogIdentitySession } from './catalogIdentitySession'
const clone = <T>(value: T): T => JSON.parse(JSON.stringify(value))
beforeEach(() => { vi.clearAllMocks(); sessionStorage.clear() })

it('reads real backend list, candidate, legacy and parent-chain fields without treating review IDs as entities', () => {
  const fixture = clone(backendJson)
  expect(fixture.book.categoryFieldKind).toBe('LEGACY'); expect(fixture.book.themes).toEqual([]); expect(fixture.book.identityRevision).toBe(0)
  for (const list of [fixture.publisherList, fixture.categoryList]) { expect(list.page).toBe(1); expect(list.size).toBeLessThanOrEqual(100); expect(list.records.every(row => typeof row.status === 'number')).toBe(true) }
  const candidates = fixture.publisherPreview.preview.book.candidates
  expect(candidates.every(candidate => Object.prototype.hasOwnProperty.call(candidate, 'id') && Object.prototype.hasOwnProperty.call(candidate, 'entityId'))).toBe(true); expect(candidates.some(candidate => candidate.id !== candidate.entityId)).toBe(true)
  const child = fixture.categoryList.records.find(row => row.parentId !== 0)!
  expect(child.path).toContain(' / '); expect(child.parentChain[child.parentChain.length - 1]?.id).toBe(child.id); expect(child.dimension).toBe('UNVERIFIED')
})

it.each(['publisher', 'theme', 'alias'] as const)('accepts actual backend %s preview and receipt with complete changes', async kind => {
  const request = clone(backendJson[`${kind}Preview`]) as unknown as CatalogIdentityRequestView, receipt = clone(backendJson[`${kind}Receipt`]) as unknown as CatalogIdentityReceipt
  const p = request.preview, b = p.book
  const input: CatalogIdentityPreviewInput = { operationKey: request.operationKey, mode: 'MANUAL', reason: p.reason, bookId: b.bookId, expectedRevision: b.expectedRevision, expectedCatalogDigest: b.catalogDigest, sourceDigest: null, changes: b.changes }
  expect(Object.keys(input.changes).sort()).toEqual(['aliases', 'categoryDimensions', 'publisher', 'themes']); expect(b.sourceStatus).toBe('MANUAL_LEGACY_EVIDENCE')
  api.preview.mockResolvedValue(request); api.confirm.mockResolvedValue(receipt); const session = useCatalogIdentitySession(receipt.actorId, () => true); await session.preview(input); expect(session.error.value).toBe(''); await session.confirm(); expect(session.receipt.value).toEqual(receipt); expect(api.confirm).toHaveBeenCalledWith(request.requestId, request.operationKey, request.previewDigest)
  if (kind === 'alias') { expect(b.aliasChanges[0]?.beforeAliases).toEqual([]); expect(b.aliasChanges[0]?.afterAliases[0]?.status).toBe('ACTIVE'); expect(b.aliasChanges[0]?.ownerId).toBe(input.changes.aliases[0]?.ownerId) }
})

it('recovers a sorted multiple-theme receipt from the service DTO after reverse input and a lost confirmation response', async () => {
  // Derive the multiple-theme variant from the frozen service DTO; validate.sortedIds
  // returns ascending categoryIds even if the caller selected the existing one first.
  const request = clone(backendJson.themePreview) as unknown as CatalogIdentityRequestView, receipt = clone(backendJson.themeReceipt) as unknown as CatalogIdentityReceipt
  const b = request.preview.book, second = clone(backendJson.categoryList.records.find(row => row.id === 9)!) as unknown as CatalogIdentityRef
  b.changes.themes = { action: 'REPLACE', categoryIds: [9, 18] }
  b.after.themes = [{ ...second, categoryId: second.id, relationKind: 'CONFIRMED' }, ...b.after.themes]
  receipt.book.applied = clone(b.changes); receipt.book.identity.themes = clone(b.after.themes)
  const value: CatalogIdentityPreviewInput = { operationKey: request.operationKey, mode: 'MANUAL', reason: request.preview.reason, bookId: b.bookId, expectedRevision: b.expectedRevision, expectedCatalogDigest: b.catalogDigest, sourceDigest: null, changes: clone(b.changes) }
  value.changes.themes!.categoryIds = [18, 9]
  api.preview.mockResolvedValue(request); api.confirm.mockRejectedValue(new Error('lost response')); api.lookup.mockRejectedValueOnce(new Error('offline')).mockResolvedValue({ ...clone(request), state: 'COMMITTED', receipt })
  const initial = useCatalogIdentitySession(receipt.actorId, () => true); await initial.preview(value); expect(initial.view.value).toEqual(request); await initial.confirm(); expect(initial.uncertain.value).toBe(true)
  const resumed = useCatalogIdentitySession(receipt.actorId, () => true); resumed.restore(); expect(resumed.input.value?.changes.themes?.categoryIds).toEqual([9, 18]); await resumed.recover()
  expect(resumed.receipt.value).toEqual(receipt); expect(resumed.uncertain.value).toBe(false); expect(api.preview).toHaveBeenCalledOnce(); expect(api.confirm).toHaveBeenCalledOnce(); expect(api.lookup).toHaveBeenLastCalledWith(value.operationKey)
  expect(value.changes.themes?.categoryIds).toEqual([18, 9]); expect(api.preview.mock.calls[0]![0].operationKey).toBe(value.operationKey)
})
